import{_ as a,o as i,c as e,ag as t}from"./chunks/framework.CZxGLIO_.js";const c=JSON.parse('{"title":"安装与首次启动","description":"选择 GooseForum 发行包、从源码构建，并完成首次启动验证。","frontmatter":{"title":"安装与首次启动","description":"选择 GooseForum 发行包、从源码构建，并完成首次启动验证。"},"headers":[],"relativePath":"docs/gooseforum/installation/index.md","filePath":"docs/gooseforum/installation/index.md"}'),o={name:"docs/gooseforum/installation/index.md"};function n(l,s,h,d,r,p){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="安装与首次启动" tabindex="-1">安装与首次启动 <a class="header-anchor" href="#安装与首次启动" aria-label="Permalink to &quot;安装与首次启动&quot;">​</a></h1><p>建议首次部署使用发行包，无需在服务器安装 Go、Node.js 或 pnpm。以下内容核对至 <strong>v0.2.122</strong>；源码构建要求以对应版本的 <code>go.mod</code> 和前端依赖为准。</p><h2 id="选择发行包" tabindex="-1">选择发行包 <a class="header-anchor" href="#选择发行包" aria-label="Permalink to &quot;选择发行包&quot;">​</a></h2><p>在 <a href="https://github.com/leancodebox/GooseForum/releases" target="_blank" rel="noreferrer">Releases</a> 选择版本，再按系统与 CPU 下载：</p><table tabindex="0"><thead><tr><th>系统</th><th>Intel / AMD 64 位</th><th>ARM 64 位</th></tr></thead><tbody><tr><td>Linux</td><td><code>GooseForum_Linux_x86_64.tar.gz</code></td><td><code>GooseForum_Linux_arm64.tar.gz</code></td></tr><tr><td>macOS</td><td><code>GooseForum_Darwin_x86_64.tar.gz</code></td><td><code>GooseForum_Darwin_arm64.tar.gz</code></td></tr><tr><td>Windows</td><td><code>GooseForum_Windows_x86_64.zip</code></td><td><code>GooseForum_Windows_arm64.zip</code></td></tr></tbody></table><p>Linux / macOS 可用 <code>uname -m</code> 查看架构：<code>x86_64</code> 对应 Intel / AMD，<code>arm64</code> 或 <code>aarch64</code> 对应 ARM。下载同一版本的 checksums 文件并核对压缩包 SHA-256；不要混用不同版本的校验值。</p><h2 id="首次启动" tabindex="-1">首次启动 <a class="header-anchor" href="#首次启动" aria-label="Permalink to &quot;首次启动&quot;">​</a></h2><p>Linux x86_64 示例，在准备长期保存数据的目录中解压并运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gooseforum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/GooseForum_Linux_x86_64.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chmod</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +x</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GooseForum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>将 <code>/path/to/</code> 换成下载目录。macOS 使用对应的 Darwin 压缩包；Windows 解压后在 PowerShell 中进入目录，运行 <code>./GooseForum.exe serve</code>。</p><p>首次运行会在工作目录生成 <code>config.toml</code>，默认配置使用 SQLite，默认端口为 <code>5234</code>。打开 <code>http://localhost:5234</code>，以启动日志中的实际端口为准。后续启动始终使用同一工作目录，否则可能读取另一份配置或创建新数据库。</p><ol><li>确认首页能够加载，注册自己的管理账号。</li><li>新数据库中 ID 为 <code>1</code> 的用户自动成为管理员；已有数据库不会因为重新部署而重新选管理员。</li><li>进入管理后台，配置站点信息并创建一个分类。</li><li>发布测试主题，验证回复、图片上传和重新登录。</li><li>按 <a href="./../administration/">后台初始化</a> 完成邮件和注册政策，再按 <a href="./../deployment/">部署</a> 开放公网访问。</li></ol><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>当前源码要求 <strong>Go 1.27+</strong>。前端建议使用 <strong>Node.js 24 LTS</strong> 和 pnpm；这是本文的构建环境建议，上游 README 中的 Node.js 18 下限不足以说明所有当前依赖的要求。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/leancodebox/GooseForum.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GooseForum</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> v0.2.122</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resource</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -ldflags=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-w -s&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>前端资源嵌入 Go 程序，顺序必须是先构建前端，再构建后端。只替换源码或前端目录不会更新已经编译的程序。跟踪 <code>main</code> 时应记录实际提交 SHA，便于复现和回退。</p><h2 id="启动异常时先看什么" tabindex="-1">启动异常时先看什么 <a class="header-anchor" href="#启动异常时先看什么" aria-label="Permalink to &quot;启动异常时先看什么&quot;">​</a></h2><ul><li>端口被占用：修改已有 <code>[server]</code> 中的 <code>port</code> 并重启。</li><li>页面看起来像全新站点：先确认工作目录、<code>config.toml</code> 和数据库路径，不要重新初始化旧数据。</li><li>编译要求更高 Go 版本：检查所选版本的 <code>go.mod</code>，或改用对应平台的发行包。</li><li>数据库迁移失败：保留日志和备份，按 <a href="./../troubleshooting/">故障排查</a> 处理。</li></ul><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/.goreleaser.yaml" target="_blank" rel="noreferrer">发行构建配置</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/README_ZH.md" target="_blank" rel="noreferrer">README</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/go.mod" target="_blank" rel="noreferrer">Go 版本</a>。</p>`,20)])])}const F=a(o,[["render",n]]);export{c as __pageData,F as default};
